//! Writes `maze-web/src/debug/eventTape/generated/<stem>.ts` — wire-tag constants, the event
//! union type, `decodeXEvent`, `isMutatingXEvent` — for one `EventSource`.

use crate::codecs;
use crate::golden::{self, GoldenEntry};
use crate::naming::{to_camel_case, to_screaming_snake};
use crate::schema::{EventSource, FieldType, MutatingMode, VariantShape, WireWidth};
use crate::type_map::{self, TsReadShape};

pub fn generate_ts_file(source: &EventSource) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "// @generated by codegen/ — DO NOT EDIT. Source: {}\n\n",
        source.location.rust_file
    ));
    emit_wire_imports(&mut out, source);
    emit_codec_imports(&mut out, source);
    out.push('\n');

    let tag_const = format!("{}_TAG", to_screaming_snake(&source.enum_name));
    emit_tags(&mut out, source, &tag_const);
    emit_type(&mut out, source);
    emit_decode(&mut out, source, &tag_const);
    emit_is_mutating(&mut out, source);
    out
}

/// Only imports the `wire.ts` primitives this source's variants actually use — a source with no
/// unit variants and no all-fixed-width struct variant never calls `expectLen`, one with no
/// standard-type field never calls the type's `ts_read_fn`, etc. Emitting the full fixed list
/// unconditionally (every source's prior behavior) left `readU32`/`readF64`/... as unused-import
/// TS6133 errors under `tsc --noEmit` for any source that doesn't happen to use every standard
/// type — real lint failures, not just noise, since this project treats a clean typecheck as a
/// build gate.
fn emit_wire_imports(out: &mut String, source: &EventSource) {
    let mut fns = std::collections::BTreeSet::new();
    let mut needs_expect_len = false;
    for v in &source.variants {
        match &v.shape {
            VariantShape::Unit => needs_expect_len = true,
            VariantShape::NewtypeTuple(field) => {
                if let FieldType::Standard(t) = &field.ty
                    && let Some(m) = type_map::lookup(t)
                {
                    fns.insert(m.ts_read_fn);
                    if matches!(m.wire_width, WireWidth::Fixed(_)) {
                        needs_expect_len = true;
                    }
                }
            }
            VariantShape::Struct(struct_fields) => {
                let mut all_fixed = true;
                for f in struct_fields {
                    if let FieldType::Standard(t) = &f.ty {
                        if let Some(m) = type_map::lookup(t) {
                            fns.insert(m.ts_read_fn);
                            if !matches!(m.wire_width, WireWidth::Fixed(_)) {
                                all_fixed = false;
                            }
                        }
                    } else {
                        all_fixed = false;
                    }
                }
                if all_fixed {
                    needs_expect_len = true;
                }
            }
        }
    }
    let mut names: Vec<&str> = fns.into_iter().collect();
    if needs_expect_len {
        names.insert(0, "expectLen");
    }
    out.push_str(&format!(
        "import {{ {} }} from \"../wire\";\n",
        names.join(", ")
    ));
}

/// Every distinct custom codec this source's variants reference gets one import from
/// `../<stem>Custom` — the hand-written sibling file the plan expects next to `eventTape/`
/// (`<stem>Custom.ts`, e.g. `kruskalCustom.ts`), not inside `generated/`.
fn emit_codec_imports(out: &mut String, source: &EventSource) {
    let mut seen = std::collections::BTreeSet::new();
    let mut seen_types = std::collections::BTreeSet::new();
    for v in &source.variants {
        let fields: Vec<&FieldType> = match &v.shape {
            VariantShape::Unit => vec![],
            VariantShape::NewtypeTuple(f) => vec![&f.ty],
            VariantShape::Struct(fields) => fields.iter().map(|f| &f.ty).collect(),
        };
        for ty in fields {
            if let FieldType::Custom(name) = ty
                && let Some(c) = codecs::lookup(name)
            {
                seen.insert(c.ts_read_fn);
                for t in c.ts_type_imports {
                    seen_types.insert(*t);
                }
            }
        }
    }
    if seen.is_empty() {
        return;
    }
    let stem_camel = to_camel_case(&source.location.stem);
    let names: Vec<&str> = seen.into_iter().collect();
    out.push_str(&format!(
        "import {{ {} }} from \"../{stem_camel}Custom\";\n",
        names.join(", ")
    ));
    if !seen_types.is_empty() {
        let type_names: Vec<&str> = seen_types.into_iter().collect();
        out.push_str(&format!(
            "import type {{ {} }} from \"../{stem_camel}Custom\";\n",
            type_names.join(", ")
        ));
    }
}

fn emit_tags(out: &mut String, source: &EventSource, tag_const: &str) {
    out.push_str(&format!("export const {tag_const} = {{\n"));
    for v in &source.variants {
        out.push_str(&format!("  {}: {},\n", to_screaming_snake(&v.name), v.tag));
    }
    out.push_str("} as const;\n\n");
}

fn emit_type(out: &mut String, source: &EventSource) {
    out.push_str(&format!("export type {} =\n", source.enum_name));
    let mut arms = Vec::new();
    for v in &source.variants {
        arms.push(match &v.shape {
            VariantShape::Unit => format!("  | {{ kind: \"{}\" }}", v.name),
            VariantShape::NewtypeTuple(field) => format!(
                "  | {{ kind: \"{}\"; {}: {} }}",
                v.name,
                to_camel_case(&field.name),
                ts_type_for(&field.ty)
            ),
            VariantShape::Struct(fields) => {
                let field_strs: Vec<String> = fields
                    .iter()
                    .map(|f| format!("{}: {}", to_camel_case(&f.name), ts_type_for(&f.ty)))
                    .collect();
                format!("  | {{ kind: \"{}\"; {} }}", v.name, field_strs.join("; "))
            }
        });
    }
    out.push_str(&arms.join("\n"));
    out.push_str(";\n\n");
}

fn ts_type_for(ty: &FieldType) -> &str {
    match ty {
        FieldType::Standard(t) => type_map::lookup(t).map(|m| m.ts_type).unwrap_or("unknown"),
        FieldType::Custom(name) => codecs::lookup(name).map(|c| c.ts_type).unwrap_or("unknown"),
    }
}

fn emit_decode(out: &mut String, source: &EventSource, tag_const: &str) {
    let name = &source.enum_name;
    out.push_str(&format!("export function decode{name}(tag: number, bytes: Uint8Array): {name} {{\n  switch (tag) {{\n"));
    for v in &source.variants {
        out.push_str(&format!(
            "    case {tag_const}.{}: {{\n",
            to_screaming_snake(&v.name)
        ));
        emit_decode_variant(out, v);
        out.push_str("    }\n");
    }
    out.push_str(&format!(
        "    default:\n      throw new Error(`{name}: unknown wire tag ${{tag}}`);\n  }}\n}}\n\n"
    ));
}

/// One field's decode: the statement(s) to emit, the expression referencing the decoded value,
/// and (for a fixed-width field) how many bytes it occupies.
struct FieldRead {
    bind_name: String,
    read_stmt: String,
    /// `Some(fixed_width)` — offset advances by a compile-time constant.
    /// `None` — the field is length-prefixed; `read_stmt` binds `{bind_name}Res.next` too, and
    /// the caller advances the running offset expression from `{bind_name}Res.next`.
    fixed_width: Option<u32>,
}

fn field_read(ty: &FieldType, offset_expr: &str, index: usize) -> FieldRead {
    let bind_name = format!("__f{index}");
    match ty {
        FieldType::Standard(t) => {
            let m = type_map::lookup(t);
            let read_fn = m.map(|m| m.ts_read_fn).unwrap_or("readUnknown");
            let value_expr = format!("{read_fn}(bytes, {offset_expr})");
            let fixed_width = m.and_then(|m| match m.wire_width {
                WireWidth::Fixed(w) => Some(w),
                WireWidth::LengthPrefixed => None,
            });
            let read_stmt = match m.map(|m| &m.ts_read_shape) {
                Some(TsReadShape::Object(field)) => {
                    format!(
                        "const {bind_name}Res = {value_expr}; const {bind_name} = {bind_name}Res.{field};"
                    )
                }
                _ => format!("const {bind_name} = {value_expr};"),
            };
            FieldRead {
                bind_name,
                read_stmt,
                fixed_width,
            }
        }
        FieldType::Custom(name) => {
            let read_fn = codecs::lookup(name)
                .map(|c| c.ts_read_fn)
                .unwrap_or("readUnknownCustom");
            FieldRead {
                bind_name: bind_name.clone(),
                read_stmt: format!(
                    "const {bind_name}Res = {read_fn}(bytes, {offset_expr}); const {bind_name} = {bind_name}Res.value;"
                ),
                fixed_width: None,
            }
        }
    }
}

fn emit_decode_variant(out: &mut String, v: &crate::schema::Variant) {
    match &v.shape {
        VariantShape::Unit => {
            out.push_str("      expectLen(tag, bytes, 0);\n");
            out.push_str(&format!("      return {{ kind: \"{}\" }};\n", v.name));
        }
        VariantShape::NewtypeTuple(field) => {
            let read = field_read(&field.ty, "0", 0);
            if let Some(w) = read.fixed_width {
                out.push_str(&format!("      expectLen(tag, bytes, {w});\n"));
            }
            out.push_str(&format!("      {}\n", read.read_stmt));
            out.push_str(&format!(
                "      return {{ kind: \"{}\", {}: {} }};\n",
                v.name,
                to_camel_case(&field.name),
                read.bind_name
            ));
        }
        VariantShape::Struct(fields) => {
            let mut offset_expr = "0".to_string();
            let mut binds = Vec::new();
            let mut all_fixed = true;
            let mut total_fixed_width = 0u32;
            let mut body = String::new();
            for (i, f) in fields.iter().enumerate() {
                let read = field_read(&f.ty, &offset_expr, i);
                body.push_str(&format!("      {}\n", read.read_stmt));
                binds.push(format!("{}: {}", to_camel_case(&f.name), read.bind_name));
                match read.fixed_width {
                    Some(w) => {
                        total_fixed_width += w;
                        offset_expr = format!("{offset_expr} + {w}");
                    }
                    None => {
                        all_fixed = false;
                        offset_expr = format!("{}Res.next", read.bind_name);
                    }
                }
            }
            // `expectLen` only applies when every field is fixed-width — a variable-length field
            // makes the total payload length itself variable, so there's no single constant to
            // check against (the individual `readNodeIdList`/`readStr` calls already validate
            // their own internal length prefix against the buffer).
            if all_fixed {
                out.push_str(&format!(
                    "      expectLen(tag, bytes, {total_fixed_width});\n"
                ));
            }
            out.push_str(&body);
            out.push_str(&format!(
                "      return {{ kind: \"{}\", {} }};\n",
                v.name,
                binds.join(", ")
            ));
        }
    }
}

fn emit_is_mutating(out: &mut String, source: &EventSource) {
    let name = &source.enum_name;
    let mutating: Vec<&str> = source
        .variants
        .iter()
        .filter(|v| v.mutating)
        .map(|v| v.name.as_str())
        .collect();
    // `tsconfig.json` has `noUnusedParameters: true` — a body that never references `event`
    // (either mode's degenerate case: always-mutating always returns `true`, per-variant with no
    // mutating variant always returns `false`) must name the parameter `_event`, or `tsc --noEmit`
    // fails on this generated file the same way it would on hand-written code.
    let references_event =
        !matches!(source.mutating_mode, MutatingMode::AlwaysMutating) && !mutating.is_empty();
    let param_name = if references_event { "event" } else { "_event" };
    out.push_str(&format!(
        "export function isMutating{name}({param_name}: {name}): boolean {{\n"
    ));
    match source.mutating_mode {
        MutatingMode::AlwaysMutating => out.push_str("  return true;\n"),
        MutatingMode::PerVariant => {
            if mutating.is_empty() {
                out.push_str("  return false;\n");
            } else {
                let checks: Vec<String> = mutating
                    .iter()
                    .map(|n| format!("event.kind === \"{n}\""))
                    .collect();
                out.push_str(&format!(
                    "  return (\n    {}\n  );\n",
                    checks.join(" ||\n    ")
                ));
            }
        }
    }
    out.push_str("}\n");
}

/// Golden round-trip test file — decodes each standard-type variant's fixed byte example and
/// compares against the same value `codegen/golden/<stem>.json` records. Mirrors the Rust-side
/// `golden_tests` module `rust_emitter` writes into `<stem>_wire.rs` — see plan section 7's
/// "защита от регрессий, не от ошибок генератора" note: this doesn't independently prove the
/// wire format is correct, only that Rust encode and TS decode still agree with each other and
/// with the last-committed golden fixture.
pub fn generate_golden_test_file(source: &EventSource, import_path: &str) -> Option<String> {
    let entries = golden::generate_golden(source);
    if entries.is_empty() {
        return None;
    }
    let name = &source.enum_name;
    let tag_const = format!("{}_TAG", to_screaming_snake(name));
    let mut out = String::new();
    out.push_str(&format!(
        "// @generated by codegen/ — DO NOT EDIT. Source: {}\n\n",
        source.location.rust_file
    ));
    out.push_str(&format!(
        "import {{ describe, it, expect }} from \"vitest\";\nimport {{ decode{name}, {tag_const} }} from \"{import_path}\";\n\n"
    ));
    out.push_str(&format!(
        "describe(\"{name} golden round trip\", () => {{\n"
    ));
    for GoldenEntry {
        variant_name,
        example_value_ts,
        expected_bytes,
        ..
    } in &entries
    {
        let bytes_lit: Vec<String> = expected_bytes.iter().map(|b| b.to_string()).collect();
        out.push_str(&format!("  it(\"{variant_name}\", () => {{\n"));
        out.push_str(&format!(
            "    const bytes = new Uint8Array([{}]);\n",
            bytes_lit.join(", ")
        ));
        out.push_str(&format!(
            "    const decoded = decode{name}({tag_const}.{}, bytes);\n",
            to_screaming_snake(variant_name)
        ));
        out.push_str(&format!(
            "    expect(decoded).toEqual({example_value_ts});\n"
        ));
        out.push_str("  });\n");
    }
    out.push_str("});\n");
    Some(out)
}

